    mgLow:["I'm not sure of our location right now.",'Tôi chưa chắc vị trí của mình lúc này.','Saya belum yakin lokasi kita sekarang.'],mgLast:['Last known simulated position: {pos} · {time}','Vị trí mô phỏng cuối: {pos} · {time}','Posisi simulasi terakhir: {pos} · {time}'],mgRestore:['Restore location confidence (demo)','Khôi phục độ tin cậy vị trí (demo)','Pulihkan keyakinan lokasi (demo)'],mgLowButton:['Low location confidence','Độ tin cậy vị trí thấp','Keyakinan lokasi rendah'],
